        {
          "id": "已确认的编写范围",
          "text": "已确认的编写范围",
          "depth": 2
        },
        {
          "id": "正式规则的目标",
          "text": "正式规则的目标",
          "depth": 2
        },
        {
          "id": "唯一定义与内容状态",
          "text": "唯一定义与内容状态",
          "depth": 2
        }
